questionvariables.text:
f_is_even : is(rand(2)=1);
g_is_even : is(rand(2)=1);
op : rand(2);                     /* 0 = sum, 1 = product */
f_parity : if f_is_even then "even" else "odd";
g_parity : if g_is_even then "even" else "odd";
opdesc : if op=0 then "addition" else "multiplication";
/* rules: even+even=even, odd+odd=odd, even+odd=neither (in general);
          even*even=even, odd*odd=even, even*odd=odd */
ta : if op=0 then (if f_is_even and g_is_even then "even" elseif (not f_is_even) and (not g_is_even) then "odd" else "neither")
     else (if f_is_even and g_is_even then "even" elseif (not f_is_even) and (not g_is_even) then "even" else "odd");
h_even : is(ta="even");
h_odd : is(ta="odd");
/* Booleans wrapped in is() so each option carries true or false, not an unevaluated equation */
opts : [["even", h_even, "Always even"],["odd", h_odd, "Always odd"],["neither", is(ta="neither"), "Could be neither (not necessarily even or odd)"]];
/* For the worked solution: h(-x) written with f(-x), g(-x), then using the parities (sign +1 for even, -1 for odd) */
sf : if f_is_even then 1 else -1;
sg : if g_is_even then 1 else -1;
hnegdef : if op=0 then f(-x)+g(-x) else f(-x)*g(-x);
hneg : if op=0 then sf*f(x)+sg*g(x) else sf*sg*f(x)*g(x);
